<script lang="ts">
  import { onMount, onDestroy, type Snippet } from 'svelte';
  import Panel from './Panel.svelte'; import Icon from '$lib/components/Icon.svelte';
  import { number as n, text, rows, type Row, type Model, type Actions } from './model';
  import { apiGet, apiPatch } from '$lib/api/client';
  import { uploadAttachment, fetchAttachmentBlob } from '$lib/api/attachments';
  import { analyzeAttachment } from '$lib/api/receipts';
  import { getParsers, uploadImport, previewImport as previewBankImport, confirmImport, getImportHistory, undoImport, type ImportSession, type ParserInfo, type ImportPreview as BankPreview } from '$lib/api/imports';
  import { exportBackup, previewImport as previewBackup, importBackup, type ImportPreview } from '$lib/api/backup';
  let { m, a, children }: { m: Model; a: Actions; children: Snippet } = $props();
  let importHistory=$state<ImportSession[]>([]);let undoTarget=$state<number|null>(null);const attachments=$derived(m.attachments);
  let busy=$state(false); let error=$state(''); let selected=$state<Row | null>(null); let previewUrl=$state(''); let receiptFilter=$state('');
  let merchant=$state(''); let receiptDate=$state(''); let total=$state<number | undefined>(); let subtotal=$state<number | undefined>(); let tax=$state<number | undefined>();
  let parsers=$state<ParserInfo[]>([]); let parser=$state('generic'); let account=$state(''); let category=$state(''); let bankPreview=$state<BankPreview | null>(null); let selectedIndexes=$state<number[]>([]);
  let backupFile=$state<unknown>(); let backupPreview=$state<ImportPreview | null>(null); let backupName=$state('');
  onMount(()=>{if(m.route==='importar')void getImportHistory().then(value=>importHistory=value).catch(report);if(m.route==='recibos'&&m.receipts[0])void selectReceipt(m.receipts[0]);if(m.route==='importar')void getParsers().then(result=>parsers=result).catch(report);});
  let receiptRequest=0;
  onDestroy(()=>{receiptRequest++;if(previewUrl)URL.revokeObjectURL(previewUrl);});
  function report(e:unknown){error=e instanceof Error?e.message:String(e);}
  async function selectReceipt(row:Row){
    const request=++receiptRequest;
    error=''; selected=null;
    if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl='';}
    try{
      const value=await apiGet<Record<string,unknown>>(`/receipts/${row.id}`);
      if(request!==receiptRequest)return;
      let nextUrl='';
      if(value.attachmentId){const blob=await fetchAttachmentBlob(n(value.attachmentId));if(request!==receiptRequest)return;nextUrl=URL.createObjectURL(blob);}
      selected={...value,id:n(value.id)};merchant=text(value.merchant);receiptDate=text(value.receiptDate).slice(0,10);total=n(value.total);subtotal=value.subtotal==null?undefined:n(value.subtotal);tax=value.tax==null?undefined:n(value.tax);previewUrl=nextUrl;
    }catch(e){if(request===receiptRequest)report(e);}
  }
  async function uploadReceipt(event:Event){const files=(event.target as HTMLInputElement).files;if(!files?.length)return;busy=true;error='';try{for(const file of Array.from(files)){const attachment=await uploadAttachment(file);await analyzeAttachment(attachment.id);}await a.refresh();a.notify(m.l('Receipts uploaded.','Recibos cargados.'));}catch(e){report(e);}finally{busy=false;}}
  async function saveReceipt(event:SubmitEvent){event.preventDefault();if(!selected)return;busy=true;try{await apiPatch(`/receipts/${selected.id}`,{merchant,receiptDate:receiptDate||null,total,subtotal,tax});await a.refresh();a.notify(m.l('Receipt saved.','Recibo guardado.'));}catch(e){report(e);}finally{busy=false;}}
  async function uploadBank(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;busy=true;error='';try{const session=await uploadImport(file,{parser,accountId:account?n(account):undefined});bankPreview=await previewBankImport(session.id);selectedIndexes=bankPreview.transactions.filter(row=>row.status==='new').map(row=>row.index);if(bankPreview.detectedAccountId)account=text(bankPreview.detectedAccountId);}catch(e){report(e);}finally{busy=false;(event.target as HTMLInputElement).value='';}}
  async function importBank(){if(!bankPreview||!account)return;busy=true;error='';try{const result=await confirmImport(bankPreview.sessionId,{accountId:n(account),defaultCategoryId:category?n(category):undefined,selectedTransactionIds:selectedIndexes});bankPreview=null;importHistory=await getImportHistory();await a.refresh();a.notify(`${result.importedCount} ${m.l('transactions imported.','movimientos importados.')}`);}catch(e){report(e);}finally{busy=false;}}
  async function undo(){if(undoTarget==null)return;busy=true;try{await undoImport(undoTarget);undoTarget=null;importHistory=await getImportHistory();await a.refresh();}catch(e){report(e);}finally{busy=false;}}
  async function analyze(id:number){busy=true;try{await analyzeAttachment(id);await a.refresh();}catch(e){report(e);}finally{busy=false;}}
  async function download(){busy=true;error='';try{const backup=await exportBackup();const url=URL.createObjectURL(new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`homeledger-${new Date().toISOString().slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);await a.refresh();}catch(e){report(e);}finally{busy=false;}}
  async function chooseBackup(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;busy=true;error='';try{backupFile=JSON.parse(await file.text());backupPreview=await previewBackup(backupFile);backupName=file.name;}catch(e){report(e);}finally{busy=false;}}
  async function restore(){busy=true;error='';try{await importBackup(backupFile,true);backupPreview=null;backupFile=undefined;await a.refresh();a.notify(m.l('Backup restored.','Respaldo restaurado.'));}catch(e){report(e);}finally{busy=false;}}
</script>
{#if error}<p class="cp-error" role="alert">{error}</p>{/if}
{#if m.route === 'configuracion'}
  <div class="cp-settings">{@render children()}</div>
{:else if m.route === 'recibos'}
  <div class="cp-toolbar"><button class="cp-button" onclick={()=>a.edit('receipts')}>{m.l('Attach / scan receipt','Adjuntar / escanear recibo')}</button><input aria-label={m.l('Filter receipts','Filtrar recibos')} bind:value={receiptFilter} placeholder={m.l('Search receipts…','Buscar recibos…')}/><label class="cp-button cp-file-button">+ {busy?'…':m.l('Upload receipt','Cargar recibo')}<input type="file" multiple accept="image/*,application/pdf,text/xml,application/xml" disabled={busy} onchange={uploadReceipt}/></label></div>
  <div class="cp-receipts-layout"><Panel title={m.l('My receipts','Mis recibos')}><div class="cp-receipt-list">{#each m.receipts.filter(row=>`${text(row.merchant)} ${text(row.filename)}`.toLowerCase().includes(receiptFilter.toLowerCase())) as row}<button class:active={selected?.id===row.id} onclick={()=>selectReceipt(row)}><span class="cp-receipt-thumb"><Icon name="file-text" size={32}/></span><span><strong>{text(row.merchant)||text(row.filename)||m.l('Receipt','Recibo')}</strong><small>{m.date(row.receiptDate)}</small><b class="cp-number">{m.money(row.total)}</b></span></button>{:else}<p class="cp-empty">{m.l('Upload a receipt to see its extracted details.','Carga un recibo para ver sus datos extraídos.')}</p>{/each}</div></Panel><Panel title={m.l('Receipt details','Detalle del recibo')}>
    {#if selected}<div class="cp-receipt-detail"><div class="cp-document">{#if previewUrl&&text(selected.mimeType).startsWith('image/')}<img src={previewUrl} alt={m.l('Uploaded receipt','Recibo cargado')}/>{:else if previewUrl&&selected.mimeType==='application/pdf'}<iframe src={previewUrl} title={m.l('Receipt PDF preview','Vista previa del recibo PDF')}></iframe>{:else}<div class="cp-paper"><h3>{merchant}</h3><p>{m.date(receiptDate)}</p><pre>{text(selected.rawText)||text(selected.filename)}</pre><strong>{m.money(total)}</strong></div>{/if}</div><form class="cp-form" onsubmit={saveReceipt}><label>{m.l('Merchant','Comercio')}<input bind:value={merchant}/></label><label>{m.l('Date','Fecha')}<input type="date" bind:value={receiptDate}/></label><div class="cp-two"><label>{m.l('Subtotal','Subtotal')}<input type="number" step="0.01" bind:value={subtotal}/></label><label>{m.l('Tax','Impuestos')}<input type="number" step="0.01" bind:value={tax}/></label></div><div class="cp-extracted-total"><span>{m.l('Total','Total')}</span><strong>{m.money(total)}</strong></div><label>{m.l('Corrected total','Total corregido')}<input type="number" step="0.01" bind:value={total}/></label><div class="cp-table-wrap"><table class="cp-table"><thead><tr><th>{m.l('Item','Concepto')}</th><th>{m.l('Quantity','Cantidad')}</th><th>{m.l('Total','Total')}</th></tr></thead><tbody>{#each rows(selected.items) as item}<tr><td>{text(item.description)}</td><td>{n(item.quantity)}</td><td>{m.money(item.total)}</td></tr>{/each}</tbody></table></div><button class="cp-button" disabled={busy}>{m.l('Save receipt','Guardar recibo')}</button><button class="cp-button ghost" type="button" onclick={()=>a.edit('receipts',selected??undefined)}>{m.l('Link transaction / edit items','Vincular movimiento / editar conceptos')}</button></form></div>{:else}<div class="cp-receipt-placeholder"><Icon name="file-text" size={68}/><p>{m.l('Choose a receipt to review its original document and extracted data.','Selecciona un recibo para revisar su documento original y los datos extraídos.')}</p></div>{/if}
  </Panel></div>
  {#if attachments.some(file=>!m.receipts.some(receipt=>receipt.attachmentId===file.id))}<Panel title={m.l('Pending documents','Documentos pendientes')}>{#each attachments.filter(file=>!m.receipts.some(receipt=>receipt.attachmentId===file.id)) as file}<div class="cp-card-footer"><span>{file.originalName||file.filename}</span><button class="cp-button ghost small" disabled={busy} onclick={()=>analyze(file.id)}>{m.l('Analyze','Analizar')}</button></div>{/each}</Panel>{/if}
{:else if m.route === 'importar'}
  <Panel title={m.l('Import transactions','Importar movimientos')}><ol class="cp-steps"><li class="active">1 {m.l('Upload file','Subir archivo')}</li><li class:active={Boolean(bankPreview)}>2 {m.l('Preview','Vista previa')}</li><li>3 {m.l('Confirm','Confirmar')}</li></ol><div class="cp-import-layout"><div class="cp-form"><label>{m.l('Bank / format','Banco / formato')}<select bind:value={parser}>{#each parsers as row}<option value={row.bankId}>{row.bankId==='generic'?m.l('Generic CSV','CSV genérico'):row.bankName}</option>{/each}</select></label><label>{m.l('Destination account','Cuenta destino')}<select bind:value={account}><option value="">{m.l('Select account','Selecciona cuenta')}</option>{#each m.accounts as row}<option value={text(row.id)}>{text(row.name)}</option>{/each}</select></label><label>{m.l('Default category','Categoría predeterminada')}<select bind:value={category}><option value="">{m.l('Automatic','Automática')}</option>{#each m.categories as row}<option value={text(row.id)}>{text(row.name)}</option>{/each}</select></label></div><label class="cp-dropzone"><Icon name="upload" size={42}/><strong>{bankPreview?.filename||m.l('Choose your bank statement','Selecciona tu estado de cuenta')}</strong><span>{m.l('CSV, Excel or supported bank format','CSV, Excel o formato bancario compatible')}</span><span class="cp-button ghost">{busy?'…':m.l('Select file','Seleccionar archivo')}</span><input type="file" accept=".csv,.xlsx,.xls,.txt" disabled={busy} onchange={uploadBank}/></label></div></Panel>
  {#if bankPreview}<Panel title={`${m.l('Preview','Vista previa')} (${bankPreview.totalCount})`}><p class="cp-muted">{bankPreview.newCount} {m.l('new','nuevos')} · {bankPreview.duplicateCount} {m.l('duplicates','duplicados')}</p><div class="cp-table-wrap"><table class="cp-table"><thead><tr><th><span class="cp-sr">{m.l('Select','Seleccionar')}</span></th><th>{m.l('Date','Fecha')}</th><th>{m.l('Description','Descripción')}</th><th>{m.l('Amount','Monto')}</th><th>{m.l('Status','Estado')}</th></tr></thead><tbody>{#each bankPreview.transactions as row}<tr><td><input type="checkbox" aria-label={row.description} checked={selectedIndexes.includes(row.index)} onchange={(event)=>selectedIndexes=event.currentTarget.checked?[...selectedIndexes,row.index]:selectedIndexes.filter(i=>i!==row.index)}/></td><td>{m.date(row.normalizedDate||row.date)}</td><td>{row.description}</td><td class="cp-number" class:cp-red={row.type==='expense'} class:cp-cyan={row.type==='income'}>{row.type==='expense'?'−':'+'}{m.money(row.amount)}</td><td>{row.status}</td></tr>{/each}</tbody></table></div><footer class="cp-card-footer"><span>{selectedIndexes.length} {m.l('selected','seleccionados')}</span><button class="cp-button" disabled={busy||!account||!selectedIndexes.length} onclick={importBank}>{m.l('Import selected transactions','Importar movimientos seleccionados')} →</button></footer></Panel>{/if}
  <Panel title={m.l('Import history','Historial de importaciones')}><div class="cp-table-wrap"><table class="cp-table"><thead><tr><th>{m.l('Date','Fecha')}</th><th>{m.l('File','Archivo')}</th><th>{m.l('Status','Estado')}</th><th></th></tr></thead><tbody>{#each importHistory as row}<tr><td>{m.date(row.createdAt)}</td><td>{row.filename}</td><td>{row.status}</td><td>{#if row.status==='completed'}<button class="cp-button ghost small" onclick={()=>undoTarget=row.id}>{m.l('Undo import','Deshacer importación')}</button>{/if}</td></tr>{:else}<tr><td colspan="4" class="cp-empty">{m.l('No imports yet.','Aún no hay importaciones.')}</td></tr>{/each}</tbody></table></div>{#if undoTarget!=null}<p>{m.l('Remove the transactions created by this import?','¿Eliminar los movimientos creados por esta importación?')}</p><div class="cp-form-actions"><button class="cp-button ghost" onclick={()=>undoTarget=null}>{m.l('Cancel','Cancelar')}</button><button class="cp-button danger" disabled={busy} onclick={undo}>{m.l('Confirm undo','Confirmar')}</button></div>{/if}</Panel><a class="cp-link" href="/respaldo">{m.l('Import or export a JSON backup','Importar o exportar respaldo JSON')} →</a>
{:else}
  <div class="cp-two"><Panel title={m.l('Export backup','Exportar respaldo')}><div class="cp-backup-action"><Icon name="database" size={45}/><p>{m.l('Download a JSON file with your accounts, transactions, categories, budgets and goals.','Descarga un archivo JSON con tus cuentas, movimientos, categorías, presupuestos y metas.')}</p><button class="cp-button" disabled={busy} onclick={download}>↓ {m.l('Download JSON','Descargar JSON')}</button></div></Panel><Panel title={m.l('Import backup','Importar respaldo')}><label class="cp-dropzone"><Icon name="upload" size={38}/><strong>{m.l('Restore a HomeLedger backup','Restaura un respaldo de HomeLedger')}</strong><span>{m.l('Select a JSON file to preview its contents first.','Selecciona un JSON para revisar primero su contenido.')}</span><span class="cp-button ghost">{m.l('Select file','Seleccionar archivo')}</span><input type="file" accept=".json,application/json" disabled={busy} onchange={chooseBackup}/></label></Panel></div>
  {#if backupPreview}<Panel title={m.l('Confirm restore','Confirmar restauración')}><p>{backupName}</p><p class="cp-red">{m.l('Importing replaces all financial data for this account. Review the counts before continuing.','La importación reemplaza todos los datos financieros de esta cuenta. Revisa las cantidades antes de continuar.')}</p><div class="cp-stats plain">{#each Object.entries(backupPreview.backupCounts).filter(([,count])=>count>0) as [key,count]}<div class="cp-stat"><span>{key}</span><strong>{count}</strong></div>{/each}</div>{#each backupPreview.warnings as warning}<p class="cp-error">{warning}</p>{/each}<div class="cp-form-actions"><button class="cp-button ghost" onclick={()=>backupPreview=null}>{m.l('Cancel','Cancelar')}</button><button class="cp-button danger" disabled={busy} onclick={restore}>{m.l('Replace data and restore','Reemplazar datos y restaurar')}</button></div></Panel>{/if}
  <Panel title={m.l('Backup history','Historial de respaldos')}><div class="cp-table-wrap"><table class="cp-table"><thead><tr><th>{m.l('Date','Fecha')}</th><th>{m.l('Operation','Operación')}</th></tr></thead><tbody>{#each m.backupHistory as row}<tr><td>{m.date(row.createdAt)}</td><td>{row.type==='export'?m.l('Export','Exportación'):m.l('Import','Importación')}</td></tr>{:else}<tr><td colspan="2" class="cp-empty">{m.l('Your backup activity will appear here.','Aquí aparecerá la actividad de tus respaldos.')}</td></tr>{/each}</tbody></table></div></Panel><a class="cp-link" href="/configuracion">{m.l('Manage scheduled snapshots in Settings','Gestiona las capturas programadas en Configuración')} →</a>
{/if}
